func newOverride() unsafe.Pointer { return unsafe.Pointer(new(jurisdictionrule.Override)) }

func newNOverride(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]jurisdictionrule.Override, n)))
}

func ptrOverride(p unsafe.Pointer, c int32) any {
	r := (*jurisdictionrule.Override)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.StateID))
	case 4:
		return &r.MaxWidthFeet
	case 5:
		return &r.MaxHeightFeet
	case 6:
		return &r.MaxLengthFeet
	case 7:
		return &r.MaxWeightPounds
	case 8:
		return &r.PermitLeadTimeDays
	case 9:
		return &r.DaylightOnly
	case 10:
		return &r.HolidayRestricted
	case 11:
		return &r.Reason
	case 12:
		return &r.Version
	case 13:
		return &r.CreatedAt
	case 14:
		return &r.UpdatedAt
	}
	return nil
}

func valueOverride(p unsafe.Pointer, c int32) any {
	r := (*jurisdictionrule.Override)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.StateID)
	case 4:
		if r.MaxWidthFeet == nil {
			return nil
		}
		return *r.MaxWidthFeet
	case 5:
		if r.MaxHeightFeet == nil {
			return nil
		}
		return *r.MaxHeightFeet
	case 6:
		if r.MaxLengthFeet == nil {
			return nil
		}
		return *r.MaxLengthFeet
	case 7:
		if r.MaxWeightPounds == nil {
			return nil
		}
		return *r.MaxWeightPounds
	case 8:
		if r.PermitLeadTimeDays == nil {
			return nil
		}
		return *r.PermitLeadTimeDays
	case 9:
		if r.DaylightOnly == nil {
			return nil
		}
		return *r.DaylightOnly
	case 10:
		if r.HolidayRestricted == nil {
			return nil
		}
		return *r.HolidayRestricted
	case 11:
		return r.Reason
	case 12:
		return r.Version
	case 13:
		return r.CreatedAt
	case 14:
		return r.UpdatedAt
	}
	return nil
}

func attachOverride(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*jurisdictionrule.Override)(p)
	switch rel {
	case 0:
		r.State = (*usstate.UsState)(child)
	}
}

func init() {
	escortThresholdsTable.Relations[0].Target = JurisdictionRulesSchema()
	jurisdictionRulesTable.Relations[0].Target = usstatedb.UsStatesSchema()
	jurisdictionRulesTable.Relations[1].Target = EscortThresholdsSchema()
	overridesTable.Relations[0].Target = usstatedb.UsStatesSchema()
}

